function validate([arr, k]) {
  if (!Array.isArray(arr) || arr.length < 1 || arr.length > 100000) return 'arr needs 1 to 10^5 values.';
  if (arr.length % 2 !== 0) return 'arr must have an even length.';
  if (arr.some(v => !Number.isInteger(v) || v < -1000000000 || v > 1000000000)) return 'Each value of arr is an integer between -10^9 and 10^9.';
  if (!Number.isInteger(k) || k < 1 || k > 100000) return 'k is an integer from 1 to 10^5.';
  return null;
}

