function canArrange(arr, k) {
  const count = new Array(k).fill(0);
  for (const value of arr) {
    const remainder = ((value % k) + k) % k;
    count[remainder]++;
  }

  if (count[0] % 2 !== 0) {
    return false;
  }
  for (let r = 1; r < k - r; r++) {
    if (count[r] !== count[k - r]) {
      return false;
    }
  }
  return k % 2 !== 0 || count[k / 2] % 2 === 0;
}

