function canArrange(arr, k) {
  // Repeatedly pair the first unmatched element with any unmatched partner whose sum is a multiple of k.
  // Every valid partner has the same remainder, so the choice among them never matters.
  const used = new Array(arr.length).fill(false);
  for (let i = 0; i < arr.length; i++) {
    if (used[i]) continue;
    used[i] = true;
    let found = false;
    for (let j = i + 1; j < arr.length && !found; j++) {
      if (!used[j] && (arr[i] + arr[j]) % k === 0) {
        used[j] = true;
        found = true;
      }
    }
    if (!found) return false;
  }
  return true;
}

