function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const limit = large ? 1000000000 : 20;
  const n = large ? 2 * pick(700, 1000) : 2 * pick(1, 5);
  const k = large ? (rand() < 0.4 ? pick(1, 12) : pick(1, 100000)) : pick(1, 8);
  const mode = rand();
  let arr;
  if (mode < 0.2) {
    arr = Array.from({ length: n }, () => pick(-limit, limit));
  } else {
    // Build matching pairs: b = t - a for a multiple t of k that keeps b within the limits.
    arr = [];
    while (arr.length < n) {
      const a = pick(-limit, limit);
      const t = k * pick(Math.ceil((a - limit) / k), Math.floor((a + limit) / k));
      arr.push(a, t - a);
    }
    // Sometimes shift one value so its remainder changes and the matching usually breaks.
    if (mode < 0.55 && k > 1) {
      const i = Math.floor(rand() * n);
      const delta = pick(1, k - 1);
      arr[i] = arr[i] + delta <= limit ? arr[i] + delta : arr[i] - delta;
    }
    for (let i = n - 1; i > 0; i--) {
      const j = Math.floor(rand() * (i + 1));
      [arr[i], arr[j]] = [arr[j], arr[i]];
    }
  }
  return [arr, k];
}
